package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_evaluation_session_candidate") public class EvaluationSessionCandidate extends RspAuditedEntity{
 public enum Invitation{PENDING,INVITED,CONFIRMED,DECLINED}public enum Attendance{PENDING,ATTENDED,NO_SHOW,EXCUSED,WITHDRAWN}
 @Column(name="session_id",nullable=false,length=36)private String sessionId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Enumerated(EnumType.STRING)@Column(name="invitation_status",nullable=false,length=20)private Invitation invitationStatus;@Enumerated(EnumType.STRING)@Column(name="attendance_status",nullable=false,length=20)private Attendance attendanceStatus;@Column(name="invited_at")private Instant invitedAt;@Column(name="confirmed_at")private Instant confirmedAt;@Column(name="attendance_recorded_by",length=100)private String attendanceRecordedBy;@Column(name="attendance_recorded_at")private Instant attendanceRecordedAt;@Column(name="attendance_reason",length=1000)private String attendanceReason;
 protected EvaluationSessionCandidate(){}public EvaluationSessionCandidate(String agency,String session,String candidate){super(agency);sessionId=requiredText(session,"sessionId");candidateId=requiredText(candidate,"candidateId");invitationStatus=Invitation.PENDING;attendanceStatus=Attendance.PENDING;}
 public void invite(Instant at){if(invitationStatus==Invitation.PENDING){invitationStatus=Invitation.INVITED;invitedAt=Objects.requireNonNull(at);}}public void confirm(Instant at){if(invitationStatus!=Invitation.INVITED)throw new IllegalStateException("Only an invited candidate may confirm");invitationStatus=Invitation.CONFIRMED;confirmedAt=Objects.requireNonNull(at);}public void attendance(Attendance value,String actor,String reason,Instant at){if(value==Attendance.PENDING)throw new IllegalArgumentException("A final attendance status is required");attendanceStatus=Objects.requireNonNull(value);attendanceRecordedBy=requiredText(actor,"actor");attendanceReason=optionalText(reason);attendanceRecordedAt=Objects.requireNonNull(at);}
 public String getSessionId(){return sessionId;}public String getCandidateId(){return candidateId;}public Invitation getInvitationStatus(){return invitationStatus;}public Attendance getAttendanceStatus(){return attendanceStatus;}public Instant getInvitedAt(){return invitedAt;}public Instant getConfirmedAt(){return confirmedAt;}public String getAttendanceRecordedBy(){return attendanceRecordedBy;}public Instant getAttendanceRecordedAt(){return attendanceRecordedAt;}public String getAttendanceReason(){return attendanceReason;}
}
